import React, { useState, useRef } from "react";
import "./App.css";

// --- Icons ---
const IconCopy = () => (
  <svg className='icon' viewBox='0 0 24 24' fill='none' stroke='currentColor' strokeWidth='2' strokeLinecap='round' strokeLinejoin='round'>
    <rect x='9' y='9' width='13' height='13' rx='2' ry='2'></rect>
    <path d='M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1'></path>
  </svg>
);

const IconCheck = () => (
  <svg
    className='icon icon-success'
    viewBox='0 0 24 24'
    fill='none'
    stroke='currentColor'
    strokeWidth='3'
    strokeLinecap='round'
    strokeLinejoin='round'
  >
    <polyline points='20 6 9 17 4 12'></polyline>
  </svg>
);

const IconUpload = () => (
  <svg className='icon icon-large' viewBox='0 0 24 24' fill='none' stroke='currentColor' strokeWidth='1' strokeLinecap='round' strokeLinejoin='round'>
    <path d='M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4'></path>
    <polyline points='17 8 12 3 7 8'></polyline>
    <line x1='12' y1='3' x2='12' y2='15'></line>
  </svg>
);

const IconSettings = () => (
  <svg className='icon' viewBox='0 0 24 24' fill='none' stroke='currentColor' strokeWidth='2' strokeLinecap='round' strokeLinejoin='round'>
    <circle cx='12' cy='12' r='3'></circle>
    <path d='M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 0 1 0 2.83 2 2 0 0 1-2.83 0l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-2 2 2 2 0 0 1-2-2v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 0 1-2.83 0 2 2 0 0 1 0-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1-2-2 2 2 0 0 1 2-2h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 0 1 0-2.83 2 2 0 0 1 2.83 0l.06.06a1.65 1.65 0 0 0 1.82.33H9a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 2-2 2 2 0 0 1 2 2v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 0 1 2.83 0 2 2 0 0 1 0 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 2 2 2 2 0 0 1-2 2h-.09a1.65 1.65 0 0 0-1.51 1z'></path>
  </svg>
);

// --- Copyable Table Cell ---
const CopyCell = ({ value }) => {
  const [copied, setCopied] = useState(false);

  const copy = () => {
    navigator.clipboard.writeText(value);
    setCopied(true);
    setTimeout(() => setCopied(false), 1500);
  };

  return (
    <div className='input-wrapper'>
      <code className='code-display'>{value}</code>
      <button className='btn-icon' onClick={copy} title='Copy'>
        {copied ? <IconCheck /> : <IconCopy />}
      </button>
    </div>
  );
};

// --- App ---
function App() {
  const [fileData, setFileData] = useState([]);
  const [headers, setHeaders] = useState([]);
  const [fileName, setFileName] = useState("");

  const [deviceId, setDeviceId] = useState("");
  const [deviceHash, setDeviceHash] = useState("");

  const [separator, setSeparator] = useState(",");
  const [hasHeaders, setHasHeaders] = useState(true);
  const [showAdvanced, setShowAdvanced] = useState(false);

  const fileInputRef = useRef(null);

  const calculateHash = async text => {
    const data = new TextEncoder().encode(text);
    const hash = await crypto.subtle.digest("SHA-256", data);
    return Array.from(new Uint8Array(hash))
      .map(b => b.toString(16).padStart(2, "0"))
      .join("");
  };

  const generateDeviceId = () => "dev_" + crypto.randomUUID().replace(/-/g, "").slice(0, 16);

  const processFile = async file => {
    const text = await file.text();
    setFileName(file.name);

    setDeviceHash(await calculateHash(text));
    setDeviceId(generateDeviceId());

    const rows = text
      .split(/\r?\n/)
      .filter(Boolean)
      .map(r => r.split(separator));

    if (hasHeaders) {
      setHeaders(rows[0]);
      setFileData(rows.slice(1));
    } else {
      setHeaders(rows[0].map((_, i) => `Column ${i + 1}`));
      setFileData(rows);
    }
  };

  return (
    <div className='app-container'>
      <main className='main-content'>
        {!fileName && (
          <div className='upload-area' onClick={() => fileInputRef.current.click()}>
            <input ref={fileInputRef} type='file' accept='.csv' hidden onChange={e => processFile(e.target.files[0])} />
            <IconUpload />
            <h3>Select .csv file</h3>
          </div>
        )}

        {fileData.length > 0 && (
          <div className='card table-card'>
            <div className='table-wrapper'>
              <table className='csv-table'>
                <thead>
                  <tr>
                    <th>#</th>
                    {headers.map((h, i) => (
                      <th key={i}>{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {fileData.map((row, r) => (
                    <tr key={r}>
                      <td className='index-col'>{r + 1}</td>
                      {row.map((cell, c) => {
                        const header = headers[c]?.toLowerCase();
                        const isAutopilotField = header === "device serial number" || header === "hardware hash";

                        return (
                          <td key={c}>{isAutopilotField ? <CopyCell value={cell} /> : <input defaultValue={cell} className='table-input' />}</td>
                        );
                      })}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}
      </main>
    </div>
  );
}

export default App;
